def get_variant(session):
    bucket = hash(session.id) % 100
    variant = 'new' if bucket < 50 else 'old'
    return variant

@app.get('/checkout')
def checkout(session):
    variant = get_variant(session)   # read here, at route entry
    log_exposure(session, variant)   # logged unconditionally, before we know if the user will even see checkout
    if some_middleware_redirects_before_render(session):
        return redirect('/cart')   # user never actually sees checkout this request -- but exposure was already logged
    return render_checkout(variant)
